    }

    //سبسٹرنگ پر مشتمل ہے۔
    اگر (normEn.includes(normalizedQuery)) {
      سکور += 50؛
      matchedAspect = 'انگریزی'؛
    } اور اگر (normEg.includes(normalizedQuery)) {
      سکور += 45؛
      matchedAspect = 'عربی مثال'؛
    } اور اگر (normFusha.includes(normalizedQuery)) {
      سکور += 40؛
      matchedAspect = 'عربی-فوشا'؛
    } اور اگر (normGrammar.includes(normalizedQuery)) {
      سکور += 35؛
      matchedAspect = 'گرامر'؛
    } اور اگر (normPurpose.includes(normalizedQuery)) {
      سکور += 30؛
      matchedAspect = 'تصور'؛
    }

    // ٹوکن میچ
